        }}

        .report-header .subtitle {{
            font-size: 1.1em;
            opacity: 0.9;
        }}

        .report-header .date {{
            margin-top: 20px;
            font-size: 0.9em;
            opacity: 0.8;
        }}

        /* KPI Dashboard */
        .kpi-dashboard {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 20px;
            margin-bottom: 30px;
        }}

        .kpi-card {{
            background: white;
            padding: 25px;
