        }}

        tr:hover {{
            background: #f8f9fa;
        }}

        tr:nth-child(even) {{
            background: #f8f9fa;
        }}

        tr:nth-child(even):hover {{
            background: #e9ecef;
        }}

        /* Insight Boxes */
        .insight-box {{
            background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
            border-left: 4px solid #048A81;
            padding: 20px;
            margin: 20px 0;
            border-radius: 0 8px 8px 0;
        }}

        .insight-box.warning {{
            border-left-color: #E07A5F;
            background: linear-gradient(135deg, #fff5f5 0%, #ffe6e6 100%);
        }}

        .insight-box h4 {{
            color: #2E4057;
            margin-bottom: 10px;
        }}

        .insight-box p {{
            color: #54494B;
            font-size: 0.95em;
        }}

        /* Executive Summary Grid */
        .exec-grid {{
            display: grid;
            grid-template-columns: 2fr 1fr;
            gap: 30px;
        }}

        @media (max-width: 900px) {{
            .exec-grid {{
                grid-template-columns: 1fr;
            }}
        }}

        .highlight-stat {{
            background: linear-gradient(135deg, #2E4057 0%, #048A81 100%);
            color: white;
            padding: 25px;
            border-radius: 10px;
            text-align: center;
        }}

        .highlight-stat .number {{
            font-size: 3em;
            font-weight: 700;
        }}

        .highlight-stat .label {{
            font-size: 1em;
            opacity: 0.9;
            margin-top: 10px;
        }}

        /* Footer */
        .footer {{
            text-align: center;
            padding: 30px;
            color: #7f8c8d;
            font-size: 0.85em;
        }}

        /* KPI Summary Row */
        .kpi-summary {{
            display: flex;
            justify-content: space-around;
            flex-wrap: wrap;
            margin: 30px 0;
            padding: 20px;
            background: #f8f9fa;
            border-radius: 10px;
        }}

        .kpi-item {{
            text-align: center;
            padding: 15px 25px;
        }}

        .kpi-item .number {{
            font-size: 1.8em;
            font-weight: 700;
