import pandas as pd
import json
from datetime import datetime

# Load data and charts
df = pd.read_pickle('/app/output/df_processed.pkl')
with open('/app/output/charts.json', 'r') as f:
    charts = json.load(f)

# Calculate all KPIs
total_revenue = df['revenue'].sum()
total_profit = df['profit'].sum()
avg_profit_margin = (df['profit'] / df['revenue']).mean() * 100
avg_order_value = df['revenue'].mean()
discount_utilization = (df['discount'] > 0).mean() * 100
total_orders = len(df)

# Year-over-year growth
yearly_revenue = df.groupby('year')['revenue'].sum()
if len(yearly_revenue) == 2:
    yoy_growth = ((yearly_revenue[2024] - yearly_revenue[2023]) / yearly_revenue[2023]) * 100
else:
    yoy_growth = 0

# Monthly trends
monthly = df.groupby(['year', 'month']).agg({
    'revenue': 'sum',
    'profit': 'sum',
    'order_id': 'count'
}).reset_index()

# Peak and low months
monthly_2024 = monthly[monthly['year'] == 2024]
peak_month_2024 = monthly_2024.loc[monthly_2024['revenue'].idxmax()]
low_month_2024 = monthly_2024.loc[monthly_2024['revenue'].idxmin()]
month_names = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

# Product performance
product_perf = df.groupby('product_id').agg({
    'revenue': 'sum',
    'profit': 'sum'
}).reset_index().sort_values('revenue', ascending=False)
top_product = product_perf.iloc[0]
top_product_count = len(product_perf[product_perf['revenue'] > 0])

# Store performance
store_perf = df.groupby('store_id').agg({
    'revenue': 'sum',
    'profit': 'sum',
    'order_id': 'count'
}).reset_index()
top_store = store_perf.loc[store_perf['revenue'].idxmax()]
num_stores = len(store_perf)

# Discount analysis
discount_buckets = pd.cut(df['discount'], bins=[-0.01, 0, 0.05, 0.10, 0.15, 0.20, 0.30, 1.0],
                          labels=['0%', '1-5%', '6-10%', '11-15%', '16-20%', '21-30%', '>30%'], observed=True)
discount_analysis = df.groupby(discount_buckets, observed=True).agg({
    'revenue': ['sum', 'mean'],
    'profit': 'sum',
    'order_id': 'count',
    'profit_margin': 'mean'
}).reset_index()
discount_analysis.columns = ['bucket', 'total_revenue', 'avg_revenue', 'total_profit', 'order_count', 'avg_margin']

# High discount analysis (>15%)
high_discount = df[df['discount'] > 0.15]
low_discount = df[df['discount'] <= 0.15]
high_discount_margin = (high_discount['profit'] / high_discount['revenue']).mean() * 100 if len(high_discount) > 0 else 0
low_discount_margin = (low_discount['profit'] / low_discount['revenue']).mean() * 100 if len(low_discount) > 0 else 0

# Customer segments
customer_lifetime = df.groupby('customer_id').agg({
    'revenue': 'sum',
    'order_id': 'count'
}).reset_index()
customer_lifetime['segment'] = pd.qcut(customer_lifetime['revenue'], q=4, labels=['Bronze', 'Silver', 'Gold', 'Platinum'])
segment_stats = customer_lifetime.groupby('segment').agg({
    'revenue': ['sum', 'mean'],
    'customer_id': 'count'
}).reset_index()
segment_stats.columns = ['segment', 'total_revenue', 'avg_revenue', 'customer_count']

# Top 10 stores for table
top_10_stores = store_perf.nlargest(10, 'revenue')[['store_id', 'revenue', 'profit', 'order_id']]
top_10_stores['profit_margin'] = (top_10_stores['profit'] / top_10_stores['revenue'] * 100).round(2)
top_10_stores['avg_order'] = (top_10_stores['revenue'] / top_10_stores['order_id']).round(2)
top_10_stores['revenue'] = top_10_stores['revenue'].round(2)
top_10_stores['profit'] = top_10_stores['profit'].round(2)

# Top 10 products for table
top_10_products = product_perf.nlargest(10, 'revenue')[['product_id', 'revenue', 'profit']]
top_10_products['profit_margin'] = (top_10_products['profit'] / top_10_products['revenue'] * 100).round(2)
top_10_products['revenue'] = top_10_products['revenue'].round(2)
top_10_products['profit'] = top_10_products['profit'].round(2)

# Quarterly performance
quarterly = df.groupby(['year', 'quarter']).agg({
    'revenue': 'sum',
    'profit': 'sum'
}).reset_index()
